{
  "findings": [
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord requires users to be at least 13 years old, but there is no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age.",
      "stance": "risk",
      "quote": "According to Discord's Terms of Service, users must be at least 13 years old— in line with U.S. privacy laws (COPPA). But there's no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord turns on some safety features by default for users aged 13 to 17, including blocking direct messages from people they don't know, hiding age-restricted servers and NSFW content, blurring sensitive images, and showing alerts when receiving messages from new contacts.",
      "stance": "mitigation",
      "quote": "For teens age 13 to 17, Discord turns on some safety features by default, including: Blocking direct messages from people they don't know; Hiding age-restricted servers and NSFW (not safe for work) content; Blurring sensitive images, and showing alerts when receiving messages from new contacts."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord marks the app as 17+ on iOS, but younger teens can still download and use it.",
      "stance": "risk",
      "quote": "Marking the app as 17+ on iOS—though younger teens can still download and use it."
    },
    {
      "ref": "[D521]",
      "area": "privacy",
      "claim": "A parent reports that Discord collects data on who your teen is messaging, which servers they've joined, and their voice call activity, but does not provide access to message content or allow setting controls through Family Center.",
      "stance": "risk",
      "quote": "What you can see: Who your teen is messaging (but not the content in the messages); Which servers they've joined; New friends added; Voice call activity (but not the calls themselves)."
    },
    {
      "ref": "[D521]",
      "area": "privacy",
      "claim": "A parent reports that Discord's Family Center requires the teen to opt in and can be left at any time without notice, and the activity history shown to parents is limited to the past seven days.",
      "stance": "mitigation",
      "quote": "It's important to know that in order to use Family Center, your teen has to opt in, and they can leave Family Center at any time without notice. The activity history that parents and caregivers can see is limited to the past seven days."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that Discord hosts servers that may contain NSFW or age-restricted content, and teens may encounter harmful or inappropriate content ranging from mild to serious, including sexual images, violent or graphic content, discussions of drugs and alcohol, hate speech, or manipulative ideologies.",
      "stance": "risk",
      "quote": "Discord hosts thousands of communities for virtually any interest imaginable. While many servers provide positive spaces for connection, teens may come across harmful or inappropriate content ranging from mild to serious, including sexual images, violent or graphic content, discussions of drugs and alcohol, hate speech, or manipulative ideologies."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that Discord automatically blurs potentially graphic media and filters content for potentially inappropriate images or video, but these filters can be turned off and may miss inappropriate text or toxic behavior in chats.",
      "stance": "mitigation",
      "quote": "Content is automatically filtered for potentially inappropriate images or video. Message request controls allow you to limit DMs from strangers. These settings can be turned off at any time."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that Discord allows strangers to send direct messages to teens unless the teen changes settings to block DMs from non-friends, and teens can be pressured by friends to spend money to access premium spaces or content.",
      "stance": "risk",
      "quote": "are highly visible and can create pressure for teens to spend in order to access premium spaces or content tied to their interests. In-game spending: Discord doesn't sell games anymore, but it integrates with platforms like Steam and Xbox. When teens see what their friends are playing, they may feel pressure to buy games or in-game items to join in."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "A parent reports that Discord does not have loot boxes or pay-to-win mechanics, but it integrates with platforms like Steam and Xbox, and teens may feel pressure to buy games or in-game items to join friends.",
      "stance": "neutral",
      "quote": "Discord doesn't sell games anymore, but it integrates with platforms like Steam and Xbox. When teens see what their friends are playing, they may feel pressure to buy games or in-game items to join in."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that Discord may track user behavior for ads or share data with third parties, but the text does not specify details about data collection or sharing practices.",
      "stance": "neutral",
      "quote": "The text does not provide specific information about data collection, tracking for ads, or sharing with third parties."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "A parent reports that there is no mention of the developer having fines, breaches, lawsuits, or regulatory actions in the provided text.",
      "stance": "neutral",
      "quote": "The text does not mention any fines, breaches, lawsuits, or regulatory actions involving the developer."
    }
  ]
}
